'use client';

// Inline "Workflows" hub — the page the Scope sidebar's Workflows menu opens
// (registered as resource `workflows`). Renders the shared gallery transparent so
// the chat stays the prominent surface; picking a workflow opens its page as an
// inline workspace tab (pageKey `workflow:<id>`, rendered by the panel's PageBody)
// — so it keeps the workspace chrome + chat alongside, instead of navigating to a
// bare standalone route.

import { useSetAtom } from 'jotai';
import { WorkflowsGallery } from '@/features/workflows-hub/workflows-gallery';
import { openWorkspaceWindowAtom } from '@/shared/stores/workspace-store';

export default function WorkflowsHub() {
  const openWindow = useSetAtom(openWorkspaceWindowAtom);
  return (
    <WorkflowsGallery
      dark
      subtitle="The standardized procedures. Pick one to view its process, run it, and review the result — all in one place."
      onOpen={(def) =>
        openWindow({ pageKey: `workflow:${def.id}`, title: def.name.replace(/^Platform Services · /, '') })
      }
    />
  );
}
